217	    const { httpAdapter } = this.adapterHost;
218	    const response = host.switchToHttp().getResponse();
219	    const responseBody = exception.getResponse() as { message: unknown };
220	    // Record every invocation so tests can assert the filter sees the
221	    // aggregated exception exactly once (never per-parameter exceptions).
222	    MyParamFilter.received.push({
223	      status: exception.getStatus(),
224	      message: responseBody.message,
225	    });
