243	      name: (exception as Error)?.name,
244	      status:
245	        typeof (exception as { getStatus?: () => number })?.getStatus ===
246	        'function'
247	          ? (exception as { getStatus: () => number }).getStatus()
248	          : undefined,
249	    };
250	    httpAdapter.reply(response, { code: 'WIDE' }, 418);
