289	    @Param('id', new NotFoundPipe()) id: string,
290	    @Query('limit', new NumberPipe('B')) limit: number,
291	  ) {
292	    recordHandler('other');
293	    return `${id},${limit}`;
294	  }
295	
296	  // The first @Param() fails with a BadRequest (collected), the second
297	  // @Param() aborts with a non-BadRequest error: the partially collected
298	  // message must die with this request.
299	  @AggregateParamErrors()
300	  @Get('partial/:id/:mode')
301	  public partial(
302	    @Param('id', new NumberPipe('A')) id: number,
303	    @Param('mode', new PartialAbortPipe()) mode: string,
304	    @Query('limit', new NumberPipe('B')) limit: number,
305	  ) {
306	    recordHandler('partial');
307	    return `${id},${mode},${limit}`;
308	  }
