339	    @Param('id', new NumberPipe('A')) id: number,
340	    @User(new CustomUserPipe()) user: { name: string },
341	    @Query('limit', new NumberPipe('B')) limit: number,
342	  ) {
343	    recordHandler('custom');
344	    return `${id},${limit},${user.name}`;
345	  }
346	
347	  // @Headers() parameters are an independent input domain: the header pipe
348	  // always runs and its transformed value reaches the handler, but a header
349	  // failure aborts the resolution immediately and discards any @Param()/
