367	  public withHeadersFiltered(
368	    @Param('id', new NumberPipe('A')) id: number,
369	    @Headers('x-token', new HeaderNumberPipe()) token: number,
370	    @Query('limit', new NumberPipe('B')) limit: number,
371	  ) {
372	    recordHandler('headersFiltered');
373	    return `${id},${token},${limit}`;
374	  }
375	
376	  // A non-BadRequest header exception propagates unchanged through the
377	  // catch-all filter; the staged param/query messages die with the request.
378	  @AggregateParamErrors()
379	  @UseFilters(MyWideFilter)
380	  @Get('headers-wide/:id')
381	  public withHeadersWide(
382	    @Param('id', new NumberPipe('A')) id: number,
383	    @Headers('x-mode', new HeaderAbortPipe()) mode: string,
