388	  }
389	
390	  // Unannotated route with a header pipe: the header pipe runs, but the
391	  // fail-fast compatibility path is unchanged.
392	  @Get('headers-legacy/:id')
393	  public withHeadersLegacy(
394	    @Param('id', new NumberPipe('A')) id: number,
395	    @Headers('x-token', new HeaderNumberPipe()) token: number,
396	    @Query('limit', new NumberPipe('B')) limit: number,
397	  ) {
398	    recordHandler('headersLegacy');
399	    return `${id},${token},${limit}`;
400	  }
401	
402	  // Delayed pipes on all three domains, used to keep mixed-failure requests
403	  // genuinely in flight at the same time in the parallel tests.
404	  @AggregateParamErrors()
405	  @Get('headers-slow/:id')
406	  public withHeadersSlow(
407	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
408	    @Headers('x-token', new SlowNumberPipe('H', 30)) token: number,
