415	  // A catch-all method filter must receive the original non-request exception
416	  // unchanged (not the aggregated BadRequest).
417	  @AggregateParamErrors()
418	  @UseFilters(MyWideFilter)
419	  @Get('wide/:id')
420	  public wide(
421	    @Param('id', new NotFoundPipe()) id: string,
422	    @Query('limit', new NumberPipe('B')) limit: number,
423	  ) {
424	    recordHandler('wide');
425	    return `${id},${limit}`;
426	  }
427	
428	  // Optional query value with a per-resolution default: when `limit` is
429	  // absent, DefaultValuePipe seeds 10 which still runs through the same
430	  // LimitPipe conversion as an explicit value. An explicit invalid value
431	  // must fail (LIMIT), never fall back to 10. `currency` is required.
432	  @AggregateParamErrors()
433	  @Get('defaults/:id')
434	  public defaults(
435	    @Param('id', new NumberPipe('A')) id: number,
436	    @Query('currency', new CurrencyPipe()) currency: string,
437	    @Query('limit', new DefaultValuePipe(10), new LimitPipe())
