442	  }
443	
444	  // Delayed variant of the defaults route used to keep a default-success and
445	  // an explicit-invalid request genuinely in flight in the parallel tests.
446	  @AggregateParamErrors()
447	  @Get('defaults-slow/:id')
448	  public defaultsSlow(
449	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
450	    @Query('currency', new CurrencyPipe()) currency: string,
451	    @Query('limit', new DefaultValuePipe(10), new SlowLimitPipe(30))
452	    limit: number,
453	  ) {
454	    recordHandler('defaultsSlow');
455	    return { id, currency, limit };
456	  }
