Now, how should the batch route be implemented? The `@Query('item')` value with repeated keys: Express (qs) gives array for repeated, string for single, undefined for missing. Fastify (fast-querystring) same behavior.

Design: a pipe `ItemsPipe` (or `BatchItemsPipe`) bound to `@Query('item')`:

```ts
class ItemsPipe implements PipeTransform {
  transform(value: string | string[] | undefined): number[] {
    if (value === undefined) {
      throw new BadRequestException('ITEM');
    }
    const values = Array.isArray(value) ? value : [value];
    const items: number[] = [];
    const messages: string[] = [];
    for (let i = 0; i < values.length; i++) {
      const raw = values[i];
      if (raw === 'deny') {
        throw new ConflictException('DENIED');
      }
      const parsed = Number(raw);
      if (raw.trim() === '' || Number.isNaN(parsed)) {
        messages.push(`ITEM[${i}]`);
        continue;
      }
      items.push(parsed);
    }
    if (messages.length > 0) {
      throw new BadRequestException(messages);
    }
    return items;
  }
}
